"""Python basics, variables and input/output, conditionals, loops."""
from dsl import fn, io

U = "python-basics"
io("print-a-banner", "Print a Banner", U, "easy", "First programs", "Write a program that prints exactly these two lines:\n\n```\nWelcome to CodePath\nLet's write Python\n```\n\nThere is no input to read.", 'print("Welcome to CodePath")\nprint("Let\'s write Python")', [("", "Welcome to CodePath\nLet's write Python\n")])
io("echo-a-word", "Echo a Word", U, "easy", "First programs", "Read one line of text and print it back unchanged.", "word = input()\nprint(word)", [("hello\n", "hello\n"), ("Python rocks\n", "Python rocks\n")], ["x\n", "  spaced  \n"])
io("greet-by-name", "Greet by Name", U, "easy", "First programs", "Read a name, then print `Hello, <name>!` on one line.", 'name = input()\nprint(f"Hello, {name}!")', [("Ada\n", "Hello, Ada!\n"), ("Grace\n", "Hello, Grace!\n")], ["Linus\n"])
fn("add-two-values", "Add Two Values", U, "easy", "Simple functions", "Write `add(a, b)` that returns the sum of two numbers.", "def add(a, b):\n    return a + b", [((2, 3), 5), ((-4, 4), 0)], [(10, 20), (0, 0), (1.5, 2.5)])
fn("rectangle-area-simple", "Area of a Rectangle", U, "easy", "Simple functions", "Write `rect_area(width, height)` that returns the area of a rectangle.", "def rect_area(width, height):\n    return width * height", [((3, 4), 12), ((5, 5), 25)], [(1, 9), (0, 7), (12, 12)])
fn("last-digit-of-number", "Last Digit of a Number", U, "easy", "Values and types", "Write `last_digit(n)` that returns the last digit of a non-negative whole number. The `%` operator gives the remainder after division.", "def last_digit(n):\n    return n % 10", [(123, 3), (7, 7)], [(90, ), (1000, ), (58, )])
fn("describe-type-name", "Name of a Type", U, "easy", "Values and types", "Write `type_name(value)` that returns the name of the value's type as text, such as `\"int\"` or `\"str\"`. Use `type(value).__name__`.", "def type_name(value):\n    return type(value).__name__", [(5, "int"), ("hi", "str")], [(2.5, ), (True, ), ([1], )])
fn("number-to-text", "Number to Text", U, "easy", "Values and types", "Write `join_number(label, n)` that returns the label, a colon, a space and the number, as one string. For example `join_number(\"Score\", 7)` gives `\"Score: 7\"`.", 'def join_number(label, n):\n    return label + ": " + str(n)', [(("Score", 7), "Score: 7"), (("Age", 30), "Age: 30")], [("X", 0), ("Total", 125)])
fn("text-to-number-double", "Double a Number Given as Text", U, "easy", "Values and types", "Write `double_text(text)` where `text` holds a whole number such as `\"21\"`. Convert it to a number and return twice its value.", "def double_text(text):\n    return int(text) * 2", [("21", 42), ("0", 0)], [("-5", ), ("100", )])

U = "variables-io"
io("sum-of-three-lines", "Sum of Three Lines", U, "easy", "Reading input", "Read three whole numbers, one per line, and print their sum.", "a = int(input())\nb = int(input())\nc = int(input())\nprint(a + b + c)", [("1\n2\n3\n", "6\n"), ("10\n-5\n0\n", "5\n")], ["7\n7\n7\n", "0\n0\n0\n"])
io("numbers-on-one-line", "Numbers on One Line", U, "easy", "Reading input", "Read one line containing two whole numbers separated by a space, and print their product. `input().split()` breaks a line into pieces.", "a, b = input().split()\nprint(int(a) * int(b))", [("3 4\n", "12\n"), ("6 7\n", "42\n")], ["0 9\n", "-2 5\n"])
io("rectangle-from-input", "Rectangle From Input", U, "easy", "Reading input", "Read the width and then the height of a rectangle, one per line. Print the area on the first line and the perimeter on the second.", "w = int(input())\nh = int(input())\nprint(w * h)\nprint(2 * (w + h))", [("3\n4\n", "12\n14\n"), ("5\n5\n", "25\n20\n")], ["1\n9\n"])
io("swap-the-order", "Swap the Order", U, "easy", "Reading input", "Read two lines of text. Print the second line first, then the first line.", "first = input()\nsecond = input()\nprint(second)\nprint(first)", [("a\nb\n", "b\na\n"), ("hello\nworld\n", "world\nhello\n")], ["1\n2\n"])
fn("quotient-and-remainder", "Quotient and Remainder", U, "easy", "Arithmetic and operators", "Write `divide(a, b)` that returns a pair: the whole-number quotient and the remainder of `a` divided by `b`. `//` gives the quotient and `%` the remainder.", "def divide(a, b):\n    return (a // b, a % b)", [((17, 5), (3, 2)), ((20, 4), (5, 0))], [(3, 7), (100, 9)])
fn("celsius-to-fahrenheit", "Celsius to Fahrenheit", U, "easy", "Arithmetic and operators", "Write `to_fahrenheit(c)` using the formula `c * 9 / 5 + 32`.", "def to_fahrenheit(c):\n    return c * 9 / 5 + 32", [(0, 32.0), (100, 212.0)], [(-40, ), (37, )])
fn("minutes-to-clock", "Minutes to Clock Time", U, "medium", "Formatting output", "Write `clock(minutes)` that turns a number of minutes into `H:MM` text, with the minutes always two digits. For example `clock(125)` gives `\"2:05\"`.", 'def clock(minutes):\n    return f"{minutes // 60}:{minutes % 60:02d}"', [(125, "2:05"), (59, "0:59")], [(60, ), (600, ), (0, )])
fn("simple-interest", "Simple Interest", U, "easy", "Arithmetic and operators", "Write `interest(principal, rate, years)` returning `principal * rate * years / 100`.", "def interest(principal, rate, years):\n    return principal * rate * years / 100", [((1000, 5, 2), 100.0), ((500, 10, 1), 50.0)], [(0, 5, 5), (250, 4, 3)])
fn("round-to-two-places", "Round to Two Places", U, "easy", "Formatting output", "Write `money(value)` that returns the value as text with exactly two decimal places. `f\"{value:.2f}\"` does this.", 'def money(value):\n    return f"{value:.2f}"', [(3.14159, "3.14"), (2, "2.00")], [(0.5, ), (10.999, )])
io("split-the-bill", "Split the Bill", U, "medium", "Formatting output", "Read a bill total, then a number of people, one per line. Print what each person pays with exactly two decimal places.", 'total = float(input())\npeople = int(input())\nprint(f"{total / people:.2f}")', [("100\n4\n", "25.00\n"), ("10\n3\n", "3.33\n")], ["99.5\n2\n", "7\n7\n"])
fn("average-of-three-values", "Average of Three", U, "easy", "Arithmetic and operators", "Write `average3(a, b, c)` that returns the average of three numbers.", "def average3(a, b, c):\n    return (a + b + c) / 3", [((1, 2, 3), 2.0), ((10, 10, 10), 10.0)], [(0, 0, 3), (-3, 0, 3)])
fn("seconds-breakdown", "Seconds Breakdown", U, "medium", "Arithmetic and operators", "Write `breakdown(seconds)` returning a list of hours, minutes and seconds. For example `breakdown(3725)` gives `[1, 2, 5]`.", "def breakdown(seconds):\n    return [seconds // 3600, seconds % 3600 // 60, seconds % 60]", [(3725, [1, 2, 5]), (59, [0, 0, 59])], [(3600, ), (0, ), (86399, )])

U = "conditionals"
fn("letter-grade", "Letter Grade", U, "easy", "Multiple branches", "Write `grade(score)` returning `\"A\"` for 90 or more, `\"B\"` for 80 or more, `\"C\"` for 70 or more, `\"D\"` for 60 or more, and `\"F\"` otherwise.", 'def grade(score):\n    if score >= 90:\n        return "A"\n    if score >= 80:\n        return "B"\n    if score >= 70:\n        return "C"\n    if score >= 60:\n        return "D"\n    return "F"', [(95, "A"), (72, "C")], [(90, ), (89, ), (60, ), (59, ), (0, ), (100, )])
fn("max-of-three", "Largest of Three", U, "easy", "Simple decisions", "Write `largest3(a, b, c)` that returns the largest of three numbers, without using `max`.", "def largest3(a, b, c):\n    best = a\n    if b > best:\n        best = b\n    if c > best:\n        best = c\n    return best", [((1, 2, 3), 3), ((9, 2, 3), 9)], [(2, 9, 3), (5, 5, 5), (-1, -2, -3)])
fn("valid-triangle-sides", "Can These Sides Form a Triangle", U, "easy", "Combined conditions", "Write `is_triangle(a, b, c)`. Three lengths form a triangle when each is positive and any two together are longer than the third.", "def is_triangle(a, b, c):\n    return a > 0 and b > 0 and c > 0 and a + b > c and a + c > b and b + c > a", [((3, 4, 5), True), ((1, 2, 3), False)], [(1, 1, 1), (0, 1, 1), (10, 1, 1), (2, 2, 3)])
fn("ticket-price-by-age", "Ticket Price by Age", U, "easy", "Multiple branches", "Write `ticket(age)` returning 0 for under 5, 8 for ages 5 to 17, 15 for ages 18 to 64, and 10 for 65 and over.", "def ticket(age):\n    if age < 5:\n        return 0\n    if age < 18:\n        return 8\n    if age < 65:\n        return 15\n    return 10", [(3, 0), (30, 15)], [(5, ), (17, ), (18, ), (64, ), (65, ), (90, )])
fn("vowel-or-consonant", "Vowel or Consonant", U, "easy", "Combined conditions", "Write `letter_kind(ch)` for a single letter. Return `\"vowel\"` for a, e, i, o, u in either case, and `\"consonant\"` otherwise.", 'def letter_kind(ch):\n    return "vowel" if ch.lower() in "aeiou" else "consonant"', [("a", "vowel"), ("z", "consonant")], [("E", ), ("Y", ), ("u", )])
fn("point-quadrant", "Which Quadrant", U, "easy", "Multiple branches", "Write `quadrant(x, y)` returning 1, 2, 3 or 4 for a point in that quadrant, and 0 if the point is on an axis.", "def quadrant(x, y):\n    if x == 0 or y == 0:\n        return 0\n    if x > 0:\n        return 1 if y > 0 else 4\n    return 2 if y > 0 else 3", [((1, 1), 1), ((-1, -1), 3)], [(-2, 3), (2, -3), (0, 5), (5, 0), (0, 0)])
fn("discount-by-amount", "Discount by Amount", U, "medium", "Multiple branches", "Write `final_price(amount)`. Orders of 1000 or more get 20% off, orders of 500 or more get 10% off, and others pay full price.", "def final_price(amount):\n    if amount >= 1000:\n        return amount * 0.8\n    if amount >= 500:\n        return amount * 0.9\n    return amount", [(1000, 800.0), (100, 100)], [(500, ), (499, ), (2000, )])
fn("divisible-by-both", "Divisible by Both", U, "easy", "Combined conditions", "Write `both(n, a, b)` that returns True only if `n` divides evenly by both `a` and `b`.", "def both(n, a, b):\n    return n % a == 0 and n % b == 0", [((12, 3, 4), True), ((10, 3, 5), False)], [(0, 2, 3), (7, 7, 7), (30, 4, 5)])
fn("days-in-a-month", "Days in a Month", U, "medium", "Combined conditions", "Write `days_in_month(month, year)`. Months are 1 to 12. February has 29 days in a leap year: a year divisible by 4, except century years not divisible by 400.", "def days_in_month(month, year):\n    if month == 2:\n        leap = (year % 4 == 0 and year % 100 != 0) or year % 400 == 0\n        return 29 if leap else 28\n    return 30 if month in (4, 6, 9, 11) else 31", [((2, 2024), 29), ((4, 2023), 30)], [(1, 2023), (2, 1900), (2, 2000), (2, 2023), (12, 1999), (9, 2001)])
fn("rock-paper-scissors", "Rock Paper Scissors", U, "medium", "Multiple branches", "Write `winner(a, b)` where each is `\"rock\"`, `\"paper\"` or `\"scissors\"`. Return `\"a\"`, `\"b\"` or `\"draw\"`.", 'def winner(a, b):\n    if a == b:\n        return "draw"\n    beats = {"rock": "scissors", "paper": "rock", "scissors": "paper"}\n    return "a" if beats[a] == b else "b"', [(("rock", "scissors"), "a"), (("rock", "paper"), "b")], [("paper", "paper"), ("scissors", "paper"), ("paper", "scissors"), ("scissors", "rock")])
fn("middle-of-three", "Middle of Three", U, "medium", "Simple decisions", "Write `middle(a, b, c)` that returns the value between the other two, without sorting.", "def middle(a, b, c):\n    if a <= b <= c or c <= b <= a:\n        return b\n    if b <= a <= c or c <= a <= b:\n        return a\n    return c", [((1, 2, 3), 2), ((9, 1, 5), 5)], [(5, 5, 1), (2, 1, 3), (7, 7, 7), (3, 8, 1)])
fn("password-strength-basic", "Basic Password Check", U, "medium", "Combined conditions", "Write `strong(password)`. Return True if it has at least 8 characters, at least one digit and at least one uppercase letter.", "def strong(password):\n    return len(password) >= 8 and any(c.isdigit() for c in password) and any(c.isupper() for c in password)", [("Secret123", True), ("short1A", False)], [("alllowercase1", ), ("NOLOWERBUTNODIGIT", ), ("Abcdefg1", ), ("", )])

U = "loops"
fn("factorial-with-a-loop", "Factorial With a Loop", U, "easy", "Running totals", "Write `factorial(n)` using a loop. The factorial of n multiplies 1, 2, up to n, and the factorial of 0 is 1.", "def factorial(n):\n    result = 1\n    for i in range(2, n + 1):\n        result *= i\n    return result", [(5, 120), (0, 1)], [(1, ), (3, ), (10, )])
fn("sum-of-evens-to-n", "Sum of Evens up to N", U, "easy", "Running totals", "Write `sum_evens(n)` returning the sum of the even numbers from 2 up to and including n.", "def sum_evens(n):\n    total = 0\n    for i in range(2, n + 1, 2):\n        total += i\n    return total", [(10, 30), (1, 0)], [(2, ), (3, ), (100, )])
fn("count-the-digits", "Count the Digits", U, "easy", "Digit loops", "Write `count_digits(n)` returning how many digits a non-negative whole number has, using a loop and no string conversion. 0 has one digit.", "def count_digits(n):\n    count = 1\n    while n >= 10:\n        n //= 10\n        count += 1\n    return count", [(12345, 5), (0, 1)], [(9, ), (10, ), (1000000, )])
fn("sum-of-digits-loop", "Sum of Digits", U, "easy", "Digit loops", "Write `digit_sum(n)` returning the sum of the digits of a non-negative whole number.", "def digit_sum(n):\n    total = 0\n    while n > 0:\n        total += n % 10\n        n //= 10\n    return total", [(123, 6), (0, 0)], [(9, ), (1001, ), (99999, )])
fn("reverse-the-digits", "Reverse the Digits", U, "medium", "Digit loops", "Write `reverse_number(n)` for a non-negative whole number, using arithmetic. For example 120 becomes 21.", "def reverse_number(n):\n    result = 0\n    while n > 0:\n        result = result * 10 + n % 10\n        n //= 10\n    return result", [(123, 321), (120, 21)], [(0, ), (7, ), (1000, ), (98765, )])
fn("power-with-a-loop", "Power With a Loop", U, "easy", "Running totals", "Write `power(base, exp)` for a non-negative `exp`, multiplying in a loop and without `**` or `pow`.", "def power(base, exp):\n    result = 1\n    for _ in range(exp):\n        result *= base\n    return result", [((2, 10), 1024), ((5, 0), 1)], [(3, 3), (0, 5), (-2, 3)])
fn("is-it-prime", "Is It Prime", U, "medium", "Counting and searching", "Write `is_prime(n)`. A prime is a whole number above 1 with no divisors other than 1 and itself. You only need to try divisors up to the square root.", "def is_prime(n):\n    if n < 2:\n        return False\n    i = 2\n    while i * i <= n:\n        if n % i == 0:\n            return False\n        i += 1\n    return True", [(7, True), (9, False)], [(1, ), (2, ), (0, ), (97, ), (100, ), (7919, )])
fn("nth-fibonacci-loop", "Nth Fibonacci Number", U, "easy", "Running totals", "Write `fib(n)` with a loop. The sequence starts 0, 1, and each number is the sum of the two before it, so `fib(0)` is 0 and `fib(6)` is 8.", "def fib(n):\n    a, b = 0, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a", [(6, 8), (0, 0)], [(1, ), (2, ), (10, ), (30, )])
fn("greatest-common-divisor-loop", "Greatest Common Divisor With a Loop", U, "medium", "Counting and searching", "Write `gcd_loop(a, b)` using Euclid's method in a loop: replace (a, b) with (b, a % b) until b is 0.", "def gcd_loop(a, b):\n    while b:\n        a, b = b, a % b\n    return a", [((12, 18), 6), ((7, 3), 1)], [(0, 5), (100, 75), (17, 17)])
fn("least-common-multiple", "Least Common Multiple", U, "medium", "Counting and searching", "Write `lcm(a, b)` returning the smallest positive number divisible by both.", "def lcm(a, b):\n    x, y = a, b\n    while y:\n        x, y = y, x % y\n    return a * b // x", [((4, 6), 12), ((3, 5), 15)], [(1, 9), (21, 6), (8, 8)])
fn("digital-root", "Digital Root", U, "medium", "Digit loops", "Write `digital_root(n)`. Repeatedly replace a non-negative number with the sum of its digits until one digit remains.", "def digital_root(n):\n    while n >= 10:\n        total = 0\n        while n:\n            total += n % 10\n            n //= 10\n        n = total\n    return n", [(942, 6), (5, 5)], [(0, ), (99, ), (123456, )])
fn("multiples-of-three-or-five", "Sum of Multiples of Three or Five", U, "easy", "Running totals", "Write `sum_multiples(limit)` returning the sum of whole numbers below `limit` divisible by 3 or 5.", "def sum_multiples(limit):\n    total = 0\n    for i in range(limit):\n        if i % 3 == 0 or i % 5 == 0:\n            total += i\n    return total", [(10, 23), (1, 0)], [(4, ), (16, ), (1000, )])
fn("star-triangle-rows", "Star Triangle", U, "easy", "Nested loops", "Write `triangle(n)` returning a list of `n` strings, where row i (from 1) holds i stars.", 'def triangle(n):\n    rows = []\n    for i in range(1, n + 1):\n        rows.append("*" * i)\n    return rows', [(3, ["*", "**", "***"]), (0, [])], [(1, ), (5, )])
fn("multiplication-grid", "Multiplication Grid", U, "medium", "Nested loops", "Write `grid(n)` returning a list of rows for an n by n multiplication table. Row 1 is `[1, 2, ..., n]`.", "def grid(n):\n    rows = []\n    for i in range(1, n + 1):\n        row = []\n        for j in range(1, n + 1):\n            row.append(i * j)\n        rows.append(row)\n    return rows", [(2, [[1, 2], [2, 4]]), (1, [[1]])], [(0, ), (3, ), (5, )])
fn("perfect-number-check", "Perfect Number", U, "medium", "Counting and searching", "Write `is_perfect(n)`. A perfect number equals the sum of its divisors smaller than itself, like 6 = 1 + 2 + 3.", "def is_perfect(n):\n    if n < 2:\n        return False\n    return sum(d for d in range(1, n) if n % d == 0) == n", [(6, True), (10, False)], [(1, ), (28, ), (496, ), (12, )])
fn("count-pairs-summing", "Count Pairs With a Sum", U, "medium", "Nested loops", "Write `count_pairs(nums, target)` counting pairs of different positions i < j where the values add up to `target`. Two nested loops are fine here.", "def count_pairs(nums, target):\n    count = 0\n    for i in range(len(nums)):\n        for j in range(i + 1, len(nums)):\n            if nums[i] + nums[j] == target:\n                count += 1\n    return count", [(([1, 2, 3, 4], 5), 2), (([1, 1, 1], 2), 3)], [([], 1), ([5], 5), ([0, 0, 0, 0], 0)])
